CREATE TABLE IF NOT EXISTS alerts(id TEXT PRIMARY KEY,symbol TEXT NOT NULL DEFAULT 'BTCUSDT',target_price DOUBLE PRECISION NOT NULL CHECK(target_price>0),condition TEXT NOT NULL CHECK(condition IN('above','below')),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','triggered','cancelled','failed')),note TEXT,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,triggered_at TIMESTAMPTZ,current_price_at_trigger DOUBLE PRECISION,email_status TEXT NOT NULL DEFAULT 'not_sent',email_error_message TEXT,push_status TEXT NOT NULL DEFAULT 'not_sent');
CREATE TABLE IF NOT EXISTS worker_state(id INTEGER PRIMARY KEY CHECK(id=1),last_price DOUBLE PRECISION,last_check_at TIMESTAMPTZ,last_error TEXT);
INSERT INTO worker_state(id)VALUES(1)ON CONFLICT(id)DO NOTHING;
